  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.18ahffj', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Comment optimiser sa rémunération en portage salarial ?'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.1dbhcig', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Votre TJM doit refléter votre expertise, votre rareté sur le marché et la valeur livrée au client. C''est particulièrement vrai pour les profils cyber, data, DevOps, cloud et pilotage IT, où l''expérience et le niveau de responsabilité changent fortement le prix de mission.'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.1fandyv', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'TJM, jours facturés, frais professionnels et accompagnement : les leviers à suivre pour mieux piloter votre rémunération nette.'),
  ('pages.blog.optimiser-remuneration-portage-salarial.auto.paragraph.1robbm7', '/blog/optimiser-remuneration-portage-salarial', 'paragraph', 'Partager cet article :'),
