  ('pages.consultants.auto.heading.qk4gm5', '/consultants', 'heading', 'Assurance chômage'),
  ('pages.consultants.auto.list_item.18knpmg', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>La négociation de votre TJM'),
  ('pages.consultants.auto.list_item.1aqzvcy', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Facturation de votre client et suivi des règlements'),
  ('pages.consultants.auto.list_item.1nuq7e3', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Le choix de vos clients et de vos missions'),
  ('pages.consultants.auto.list_item.1tzoiuk', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Traitement des frais professionnels justifiés'),
  ('pages.consultants.auto.list_item.5ofuxr', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Responsabilité civile professionnelle'),
  ('pages.consultants.auto.list_item.6ie92', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Votre organisation et votre temps de travail'),
  ('pages.consultants.auto.list_item.opt9zb', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>La relation opérationnelle avec le client'),
  ('pages.consultants.auto.list_item.thii28', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Contrat de travail en CDI, statut cadre'),
  ('pages.consultants.auto.list_item.ujvowh', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Votre positionnement et votre offre'),
  ('pages.consultants.auto.list_item.uqzipq', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Un interlocuteur unique pendant toute la mission'),
  ('pages.consultants.auto.list_item.vmxen7', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Contrat de prestation avec l’entreprise cliente'),
  ('pages.consultants.auto.list_item.x3d3np', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Paie, déclarations sociales et fiscales'),
  ('pages.consultants.auto.list_item.ynwqno', '/consultants', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>La qualité et les livrables de votre intervention'),
  ('pages.consultants.auto.paragraph.10n12s0', '/consultants', 'paragraph', 'Partie 2 · Votre quotidien'),
  ('pages.consultants.auto.paragraph.10u9s5a', '/consultants', 'paragraph', 'Architecture et intégration'),
  ('pages.consultants.auto.paragraph.15kwctg', '/consultants', 'paragraph', 'Les aléas'),
  ('pages.consultants.auto.paragraph.18ahffj', '/consultants', 'paragraph', 'Votre quotidien'),
  ('pages.consultants.auto.paragraph.18ldtpn', '/consultants', 'paragraph', 'Une simulation de salaire chiffrée, l’infographie des frais professionnels, le mode opératoire et une formation à LAYA, notre outil de gestion. Puis une intégration individuelle, en visioconférence ou sur place.'),
  ('pages.consultants.auto.paragraph.193cqcp', '/consultants', 'paragraph', 'Ce que vous gardez'),
  ('pages.consultants.auto.paragraph.1b3pvb9', '/consultants', 'paragraph', 'Mission en France ou à l’étranger, pour un client français ou étranger, en télétravail ou sur site.'),
  ('pages.consultants.auto.paragraph.1bpp3an', '/consultants', 'paragraph', 'Vous pouvez vous constituer votre propre clientèle et en rester pleinement responsable. Nous vous proposons aussi des missions issues de nos partenaires.'),
  ('pages.consultants.auto.paragraph.1bwi7b4', '/consultants', 'paragraph', 'Pour qui ?'),
  ('pages.consultants.auto.paragraph.1ca88fd', '/consultants', 'paragraph', 'Cloud, DevOps et SRE'),
  ('pages.consultants.auto.paragraph.1dl8w0r', '/consultants', 'paragraph', 'Le 1er mois'),
  ('pages.consultants.auto.paragraph.1e907ml', '/consultants', 'paragraph', 'Chronologie'),
  ('pages.consultants.auto.paragraph.1f7fpoy', '/consultants', 'paragraph', 'Vous acquérez 2,5 jours ouvrés de congés payés par mois. Ils vous sont versés directement sur votre bulletin, sous l’intitulé « Indemnités de congés payés » — ou provisionnés sur votre compte de trésorerie, pour partir en congés en maintenant votre rémunération.'),
  ('pages.consultants.auto.paragraph.1fctzph', '/consultants', 'paragraph', 'Chefs de projet IT, PMO et AMOA'),
  ('pages.consultants.auto.paragraph.1gx6eeu', '/consultants', 'paragraph', 'Chaque mois'),
  ('pages.consultants.auto.paragraph.1jjqzp0', '/consultants', 'paragraph', 'Vous pouvez mettre une part de votre rémunération brute de côté sur un compte de trésorerie dédié : pour lisser une paie d’un mois sur l’autre, financer des congés, provisionner une fin de contrat ou débloquer un acompte selon vos besoins.'),
  ('pages.consultants.auto.paragraph.1k8zyd3', '/consultants', 'paragraph', 'Comme tout salarié, vous percevez des indemnités journalières de la Sécurité sociale, avec un relais de la prévoyance sur les arrêts longs. Les congés maternité et paternité s’appliquent dans les mêmes conditions que pour un salarié classique.'),
  ('pages.consultants.auto.paragraph.1kao9sa', '/consultants', 'paragraph', 'Avec un emploi salarié, sous réserve de l’accord de votre employeur et d’un maximum de 48 heures hebdomadaires cumulées. Ou avec une retraite.'),
  ('pages.consultants.auto.paragraph.1kx3w6b', '/consultants', 'paragraph', 'Cybersécurité, GRC et gouvernance'),
  ('pages.consultants.auto.paragraph.1n6rins', '/consultants', 'paragraph', 'Votre entrée'),
  ('pages.consultants.auto.paragraph.1nzigs2', '/consultants', 'paragraph', 'Ce que The Porters gère'),
  ('pages.consultants.auto.paragraph.1rvb5sc', '/consultants', 'paragraph', 'Ni chez votre client, ni chez The Porters. Vous êtes salarié sur la forme, autonome sur le fond.'),
  ('pages.consultants.auto.paragraph.1va7ktl', '/consultants', 'paragraph', 'Démission, rupture de période d’essai ou rupture conventionnelle : dans tous les cas nous vous remettons le solde de tout compte, le certificat de travail, l’attestation destinée à France Travail et le reçu pour solde de tout compte. Une rupture conventionnelle suppose des fonds suffisants sur votre compte de trésorerie pour couvrir la prime et les frais associés.'),
  ('pages.consultants.auto.paragraph.1ydwavb', '/consultants', 'paragraph', 'Votre trésorerie'),
  ('pages.consultants.auto.paragraph.4ouu68', '/consultants', 'paragraph', 'Vous cotisez chaque mois à l’assurance chômage et conservez vos droits, comme tout salarié.'),
  ('pages.consultants.auto.paragraph.bq2yi8', '/consultants', 'paragraph', 'Data, IA et machine learning'),
  ('pages.consultants.auto.paragraph.cgk3os', '/consultants', 'paragraph', 'Scrum Masters et Agile Coaches'),
  ('pages.consultants.auto.paragraph.d84s1l', '/consultants', 'paragraph', 'Vos congés'),
  ('pages.consultants.auto.paragraph.f0xscj', '/consultants', 'paragraph', 'La page précédente explique le cadre. Celle-ci décrit ce qui se passe réellement : votre entrée, votre premier salaire, vos congés, un arrêt maladie, votre trésorerie, et le jour où vous partez. Y compris la sortie — que personne ne documente.'),
  ('pages.consultants.auto.paragraph.jwielf', '/consultants', 'paragraph', 'Le statut cadre vous permet de cotiser au régime général et à la retraite complémentaire.'),
  ('pages.consultants.auto.paragraph.m29l4s', '/consultants', 'paragraph', 'Le simulateur répond en quelques minutes. Un conseiller reprend ensuite vos hypothèses avec vous.'),
  ('pages.consultants.auto.paragraph.p9arsy', '/consultants', 'paragraph', 'Votre sortie'),
  ('pages.consultants.auto.paragraph.pc2pk8', '/consultants', 'paragraph', 'Votre contrat de travail est établi, le contrat de prestation signé avec votre client, et votre chiffre d’affaires devient un salaire.'),
  ('pages.consultants.auto.paragraph.qrkykr', '/consultants', 'paragraph', 'Une question ?'),
  ('pages.consultants.auto.paragraph.qwjkxi', '/consultants', 'paragraph', 'Sept étapes, dans l’ordre où vous les vivrez.'),
  ('pages.consultants.auto.paragraph.v4o23j', '/consultants', 'paragraph', 'Product Owners et Product Managers'),
  ('pages.consultants.auto.paragraph.x8100t', '/consultants', 'paragraph', 'Vous déclarez votre compte rendu d’activité et vos notes de frais. Nous facturons votre client, établissons la paie et traitons les déclarations sociales. Deux sessions de paie existent, selon la date de votre déclaration.'),
  ('pages.consultants.auto.paragraph.xxeyen', '/consultants', 'paragraph', 'À savoir'),
  ('pages.consultants.auto.paragraph.yorddf', '/consultants', 'paragraph', 'Les métiers que nous portons toute l’année. Si le vôtre n’y est pas mais relève de la prestation intellectuelle, il est très probablement éligible.'),
