  ('pages.entreprises.auto.heading.slc1qt', '/entreprises', 'heading', 'Un besoin précis à couvrir ? <span class="gold-underline">Décrivez le contexte.</span>'),
  ('pages.entreprises.auto.list_item.1329hdf', '/entreprises', 'list_item', '<span class="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Contrat, paie et facturation pris en charge'),
  ('pages.entreprises.auto.list_item.1cufqdc', '/entreprises', 'list_item', '<span class="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Cadre salarial sécurisé'),
  ('pages.entreprises.auto.list_item.1lh2k4h', '/entreprises', 'list_item', '<span class="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Suivi opérationnel cadré'),
  ('pages.entreprises.auto.list_item.25pikb', '/entreprises', 'list_item', '<span class="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Sourcing IT ciblé'),
  ('pages.entreprises.auto.list_item.df29ag', '/entreprises', 'list_item', '<span class="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Choix du modèle selon le besoin'),
  ('pages.entreprises.auto.list_item.lne74i', '/entreprises', 'list_item', '<span class="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Interlocuteur unique pendant la mission'),
  ('pages.entreprises.auto.paragraph.10n12s0', '/entreprises', 'paragraph', 'Entreprises'),
  ('pages.entreprises.auto.paragraph.15kwctg', '/entreprises', 'paragraph', 'Validation interne pilotée par les référents technique et commercial, et l’avis d’un tiers expert sur les profils stratégiques. Les profils vous sont ensuite transmis sous forme anonymisée.'),
  ('pages.entreprises.auto.paragraph.17ysdw7', '/entreprises', 'paragraph', 'Avant le premier CV'),
  ('pages.entreprises.auto.paragraph.19o2dms', '/entreprises', 'paragraph', 'Chaque mission est suivie par un binôme, avec un relais identifié. Si votre interlocuteur est absent, votre dossier ne s’arrête pas.'),
  ('pages.entreprises.auto.paragraph.19swiy2', '/entreprises', 'paragraph', 'Analyste programmeur, chef de projet applicatif.'),
  ('pages.entreprises.auto.paragraph.1b3pvb9', '/entreprises', 'paragraph', 'Architecture, migration, CI/CD, infrastructure as code, conteneurisation, observabilité, sécurité des environnements.'),
  ('pages.entreprises.auto.paragraph.1bpp3an', '/entreprises', 'paragraph', 'Applications métier sur socles anciens mais critiques pour la production, IBM i / AS400 compris, autant que sur des stacks récentes.'),
  ('pages.entreprises.auto.paragraph.1cevmd8', '/entreprises', 'paragraph', 'Contractualisation, ouverture des accès, intégration aux outils et aux processus déjà en place. Les profils sont transmis sous forme anonymisée.'),
  ('pages.entreprises.auto.paragraph.1cr3648', '/entreprises', 'paragraph', 'Habilitations, charte de sécurité, confidentialité, lieux d’exécution autorisés.'),
  ('pages.entreprises.auto.paragraph.1dl8w0r', '/entreprises', 'paragraph', 'CIGREF, SYNTEC et ROME servent de grille de lecture : compétences attendues, niveaux d’expertise, pratiques professionnelles, expérience sectorielle.'),
  ('pages.entreprises.auto.paragraph.1e907ml', '/entreprises', 'paragraph', 'Notre processus de sélection'),
  ('pages.entreprises.auto.paragraph.1gx6eeu', '/entreprises', 'paragraph', 'Un entretien RH et motivation. Un entretien de compétences mené par un référent interne : technologies maîtrisées, méthodes de travail, sécurité du SI, problèmes rencontrés et solutions mises en œuvre. Grilles d’évaluation standardisées, pour que deux profils restent comparables.'),
  ('pages.entreprises.auto.paragraph.1hkia6c', '/entreprises', 'paragraph', 'Un profil ne se qualifie pas contre une fiche de poste, mais contre un contexte. Ces cinq points sont fixés au cadrage, par écrit.'),
  ('pages.entreprises.auto.paragraph.1id3tdl', '/entreprises', 'paragraph', 'Entreprises'),
  ('pages.entreprises.auto.paragraph.1k0re0f', '/entreprises', 'paragraph', 'Trois exemples réels, décrits par leur contexte technique et les profils mobilisés. Les noms de clients ne sont pas publiés.'),
  ('pages.entreprises.auto.paragraph.1kao9sa', '/entreprises', 'paragraph', 'Cadrage de cas d’usage, ingénierie et pipelines, gouvernance, industrialisation et mise en production des modèles.'),
  ('pages.entreprises.auto.paragraph.1n6rins', '/entreprises', 'paragraph', 'Nous regardons les missions effectivement réalisées, les environnements techniques réellement pratiqués et les responsabilités réellement assumées. Pas les mots-clés du CV.'),
  ('pages.entreprises.auto.paragraph.1n85qbc', '/entreprises', 'paragraph', 'Applications métier cœur du logement social : analyse des besoins, développements spécifiques, maintenance corrective et évolutive.'),
  ('pages.entreprises.auto.paragraph.1ny7ybr', '/entreprises', 'paragraph', 'Qui décide, qui valide, avec quelles équipes le consultant travaillera au quotidien.'),
  ('pages.entreprises.auto.paragraph.1nzigs2', '/entreprises', 'paragraph', 'Sourcing et traçabilité'),
  ('pages.entreprises.auto.paragraph.1rvb5sc', '/entreprises', 'paragraph', 'Développement, architecture, intégration, tests, infrastructure ou pilotage sur un périmètre défini.'),
  ('pages.entreprises.auto.paragraph.1sprkjd', '/entreprises', 'paragraph', 'Prestation via l’ESN du groupe'),
  ('pages.entreprises.auto.paragraph.1z017i4', '/entreprises', 'paragraph', 'Technique, fonctionnel ou organisationnel. Le point commun : une mission définie et des responsabilités lisibles.'),
  ('pages.entreprises.auto.paragraph.2fdx2y', '/entreprises', 'paragraph', 'Nous qualifions le besoin : périmètre, environnement technique, contraintes de sécurité et de conformité, mode de fonctionnement attendu.'),
  ('pages.entreprises.auto.paragraph.3h463v', '/entreprises', 'paragraph', 'Profils mobilisés'),
  ('pages.entreprises.auto.paragraph.41bvfy', '/entreprises', 'paragraph', 'Quatre temps, et à chacun ce que nous prenons en charge.'),
  ('pages.entreprises.auto.paragraph.46k8nl', '/entreprises', 'paragraph', 'Analyse du parcours réel, évaluation sur référentiels métiers (CIGREF, SYNTEC, ROME), entretiens structurés — RH et technique — puis tests ou mise en situation lorsque le périmètre l’exige.'),
  ('pages.entreprises.auto.paragraph.4ouu68', '/entreprises', 'paragraph', 'Product Ownership, Scrum, coaching, coordination multi-équipes, conduite du changement. Nos consultants s’alignent sur vos processus existants plutôt que d’imposer un cadre.'),
  ('pages.entreprises.auto.paragraph.5vv7ya', '/entreprises', 'paragraph', 'Portage salarial'),
  ('pages.entreprises.auto.paragraph.9f1zwi', '/entreprises', 'paragraph', 'Le point de départ n’est pas le statut, mais votre besoin : sécuriser un consultant déjà identifié, ou trouver une expertise à mobiliser.'),
  ('pages.entreprises.auto.paragraph.b0298z', '/entreprises', 'paragraph', 'Points d’avancement à une fréquence définie au cadrage, avec un relais identifié dans l’équipe pour qu’aucun suivi ne dépende d’une seule personne.'),
  ('pages.entreprises.auto.paragraph.c26d2', '/entreprises', 'paragraph', 'Profils mobilisés'),
  ('pages.entreprises.auto.paragraph.cuasbt', '/entreprises', 'paragraph', 'The Porters met en place le cadre contractuel, salarial et administratif. Vous gardez une relation opérationnelle simple, avec une facture unique.'),
  ('pages.entreprises.auto.paragraph.d84s1l', '/entreprises', 'paragraph', 'Selon le niveau d’exigence du périmètre : tests techniques, questionnaires métier, études de cas. La disponibilité réelle est vérifiée à ce stade — délai de démarrage, durée, compatibilité géographique.'),
  ('pages.entreprises.auto.paragraph.etmf9e', '/entreprises', 'paragraph', 'La date de démarrage réelle, la durée, et ce qui dépend d’un jalon que vous ne maîtrisez pas.'),
  ('pages.entreprises.auto.paragraph.f0xscj', '/entreprises', 'paragraph', 'Un besoin précis à couvrir ou une équipe projet à structurer ? Nous cadrons cinq points, puis nous sélectionnons en cinq étapes. Pas de plaquette.'),
  ('pages.entreprises.auto.paragraph.fn9v2j', '/entreprises', 'paragraph', 'Nous revenons vers vous avec des profils, pas avec une plaquette.'),
  ('pages.entreprises.auto.paragraph.gdhka1', '/entreprises', 'paragraph', 'Deux cadres contractuels'),
  ('pages.entreprises.auto.paragraph.j451bx', '/entreprises', 'paragraph', 'Cooptation, événements IT, LesJeudis, HelloWork, Meteojob, LinkedIn, Indeed, Monster, France Travail. Le vivier est organisé autour d’une cartographie métiers, pas d’une pile de CV.'),
  ('pages.entreprises.auto.paragraph.jwielf', '/entreprises', 'paragraph', 'Gouvernance de la sécurité, audit, analyse de risques et de conformité, sensibilisation des équipes. RSSI, RSSI de transition, chef de projet et ingénieur cybersécurité.'),
  ('pages.entreprises.auto.paragraph.k0wnv', '/entreprises', 'paragraph', 'Passage de Hortonworks à Cloudera Data Platform pour un organisme public national.'),
  ('pages.entreprises.auto.paragraph.l181hd', '/entreprises', 'paragraph', 'Architecte système, expert Big Data, développeur senior.'),
  ('pages.entreprises.auto.paragraph.m29l4s', '/entreprises', 'paragraph', 'Types de missions'),
  ('pages.entreprises.auto.paragraph.noit25', '/entreprises', 'paragraph', 'Audit de l’existant, recommandations d’outils, mise en place d’applicatifs internes chez un industriel.'),
  ('pages.entreprises.auto.paragraph.pkrtle', '/entreprises', 'paragraph', 'The Big Porters, l’ESN du groupe, prend le sourcing et le pilotage du renfort. Même vivier, même processus de sélection, cadre contractuel différent.'),
  ('pages.entreprises.auto.paragraph.q9609p', '/entreprises', 'paragraph', 'Un renfort qui exécute et un expert qui arbitre ne sont pas le même profil, ni le même TJM.'),
  ('pages.entreprises.auto.paragraph.qrkykr', '/entreprises', 'paragraph', 'Une question ?'),
  ('pages.entreprises.auto.paragraph.qwjkxi', '/entreprises', 'paragraph', 'Structuré, homogène, traçable. C’est ce qui permet de comparer deux candidats sur la même grille plutôt que sur une impression d’entretien.'),
  ('pages.entreprises.auto.paragraph.sjpd3r', '/entreprises', 'paragraph', 'Architecte données, data scientist, développeur fullstack.'),
  ('pages.entreprises.auto.paragraph.ts2z9y', '/entreprises', 'paragraph', 'CIGREF, SYNTEC et ROME donnent la grille de lecture : compétences attendues, niveaux d’expertise, pratiques professionnelles, expérience sectorielle.'),
  ('pages.entreprises.auto.paragraph.v5809w', '/entreprises', 'paragraph', 'Les socles en place, leur âge, leurs contraintes, et ce qui ne peut pas être arrêté.'),
  ('pages.entreprises.auto.paragraph.vx7sjf', '/entreprises', 'paragraph', 'Vous recevez le parcours, les compétences et la disponibilité. L’identité vient après votre intérêt, dans le respect des règles de protection des données personnelles.'),
  ('pages.entreprises.auto.paragraph.x1sfc', '/entreprises', 'paragraph', 'Profils mobilisés'),
  ('pages.entreprises.auto.paragraph.xxeyen', '/entreprises', 'paragraph', 'Périmètres couverts'),
  ('pages.equipe.auto.button.1ur26yk', '/equipe', 'button', 'The Porters'),
  ('pages.equipe.auto.button.4nxp4q', '/equipe', 'button', 'Accueil'),
  ('pages.equipe.auto.button.mq50re', '/equipe', 'button', 'Voir nos offres'),
  ('pages.equipe.auto.heading.1167sah', '/equipe', 'heading', 'Vous voulez rejoindre l’équipe ?'),
  ('pages.equipe.auto.heading.177rpc6', '/equipe', 'heading', 'Suivi de mission'),
  ('pages.equipe.auto.heading.1ozy636', '/equipe', 'heading', 'Une personne connaît votre dossier. <span class="gold-underline">Toujours la même.</span>'),
  ('pages.equipe.auto.heading.1xllver', '/equipe', 'heading', 'Facturation et paie'),
  ('pages.equipe.auto.heading.dfrznt', '/equipe', 'heading', 'Conseil et cadrage'),
  ('pages.equipe.auto.heading.nuwkp8', '/equipe', 'heading', 'Contrats et conformité'),
  ('pages.equipe.auto.paragraph.18ahffj', '/equipe', 'paragraph', 'Notre équipe'),
  ('pages.equipe.auto.paragraph.1jasppu', '/equipe', 'paragraph', 'Votre compte rendu d’activité, la facture au client, vos frais, votre bulletin. Deux sessions de paie par mois.'),
  ('pages.equipe.auto.paragraph.1sve2ab', '/equipe', 'paragraph', 'L’équipe'),
  ('pages.equipe.auto.paragraph.1xxwf87', '/equipe', 'paragraph', 'Les deux contrats, qui s’engage sur quoi, et les contraintes de sécurité ou de confidentialité du client.'),
  ('pages.equipe.auto.paragraph.36ekrk', '/equipe', 'paragraph', 'Quatre fonctions, un interlocuteur unique par consultant, et un binôme derrière lui pour qu’aucun suivi ne dépende d’une seule personne.'),
  ('pages.equipe.auto.paragraph.7dkowk', '/equipe', 'paragraph', 'Votre situation, votre statut actuel, votre TJM cible. On chiffre avant de contractualiser.'),
  ('pages.equipe.auto.paragraph.famhfh', '/equipe', 'paragraph', 'Points d’avancement à une fréquence définie au départ, avec un relais identifié si votre interlocuteur est absent.'),
  ('pages.equipe.auto.paragraph.pyzpvb', '/equipe', 'paragraph', 'Les postes ouverts sont publiés sur notre espace HelloWork.'),
  ('pages.equipe.auto.paragraph.qrkykr', '/equipe', 'paragraph', 'Une question ?'),
  ('pages.espace-client.auto.button.1ssya12', '/espace-client', 'button', 'Créer mon accès'),
  ('pages.espace-client.auto.button.4nxp4q', '/espace-client', 'button', 'Accueil'),
  ('pages.espace-client.auto.button.n0p4t', '/espace-client', 'button', 'Demander mon lien'),
  ('pages.espace-client.auto.heading.137fo19', '/espace-client', 'heading', 'Je n’ai pas encore d’accès'),
  ('pages.espace-client.auto.heading.1co03gw', '/espace-client', 'heading', 'J’ai déjà un accès'),
  ('pages.espace-client.auto.heading.1nsallb', '/espace-client', 'heading', 'LAYA : vos bulletins, vos CRA, votre trésorerie.'),
  ('pages.espace-client.auto.paragraph.10n12s0', '/espace-client', 'paragraph', 'Espace The Porters'),
  ('pages.espace-client.auto.paragraph.12kpjtd', '/espace-client', 'paragraph', 'Écrivez à <a class="font-semibold text-porters-white underline decoration-porters-gold underline-offset-4" href="mailto:contact@porters.fr">contact@porters.fr</a>'),
  ('pages.espace-client.auto.paragraph.1bwi7b4', '/espace-client', 'paragraph', 'Déjà accompagné'),
  ('pages.espace-client.auto.paragraph.1id3tdl', '/espace-client', 'paragraph', 'Espace client'),
  ('pages.espace-client.auto.paragraph.1kx3w6b', '/espace-client', 'paragraph', 'Nouvel accès'),
  ('pages.espace-client.auto.paragraph.bq2yi8', '/espace-client', 'paragraph', 'Précisez si vous êtes consultant ou entreprise. Un conseiller ouvre votre accès et vous transmet vos identifiants.'),
  ('pages.espace-client.auto.paragraph.f0xscj', '/espace-client', 'paragraph', 'LAYA est notre outil de gestion. Vous y retrouvez vos bulletins de salaire, vos comptes rendus d’activité, vos notes de frais et votre compte de trésorerie. Toutes les communications internes y passent.'),
  ('pages.espace-client.auto.paragraph.gfzgru', '/espace-client', 'paragraph', 'Besoin d''aide ?'),
  ('pages.espace-client.auto.paragraph.qrkykr', '/espace-client', 'paragraph', 'Une question ?'),
  ('pages.espace-client.auto.paragraph.yorddf', '/espace-client', 'paragraph', 'Nous vérifions votre identité et vous renvoyons le lien de connexion associé à votre dossier.'),
  ('pages.expertises.agilite-coaching.auto.button.1avc626', '/expertises/agilite-coaching', 'button', 'Prendre rendez-vous'),
  ('pages.expertises.agilite-coaching.auto.button.1ur26yk', '/expertises/agilite-coaching', 'button', 'Consultants'),
  ('pages.expertises.agilite-coaching.auto.button.4nxp4q', '/expertises/agilite-coaching', 'button', 'Accueil'),
  ('pages.expertises.agilite-coaching.auto.button.nviywh', '/expertises/agilite-coaching', 'button', 'Parler à un conseiller'),
  ('pages.expertises.agilite-coaching.auto.button.wvc156', '/expertises/agilite-coaching', 'button', 'Simuler mes revenus'),
  ('pages.expertises.agilite-coaching.auto.heading.1co03gw', '/expertises/agilite-coaching', 'heading', 'L’agilité sert la valeur, pas les rituels'),
  ('pages.expertises.agilite-coaching.auto.heading.1hlyx01', '/expertises/agilite-coaching', 'heading', 'Une méthode visible. Une valeur compréhensible.'),
  ('pages.expertises.agilite-coaching.auto.heading.1ia250k', '/expertises/agilite-coaching', 'heading', 'Votre prochaine mission commence par un cadre clair.'),
  ('pages.expertises.agilite-coaching.auto.heading.1nsallb', '/expertises/agilite-coaching', 'heading', 'Portage salarial pour profils Agilité, Produit et Transformation'),
  ('pages.expertises.agilite-coaching.auto.heading.1ot5ix6', '/expertises/agilite-coaching', 'heading', 'Des missions où votre expertise fait la différence'),
  ('pages.expertises.agilite-coaching.auto.heading.1xptkyn', '/expertises/agilite-coaching', 'heading', 'Des profils reconnus pour ce qu’ils apportent au projet'),
  ('pages.expertises.agilite-coaching.auto.heading.b2ff2g', '/expertises/agilite-coaching', 'heading', 'Repères de méthode'),
  ('pages.expertises.agilite-coaching.auto.heading.ktdkib', '/expertises/agilite-coaching', 'heading', 'Transformation accompagnée'),
