  ('pages.expertises.agilite-coaching.auto.heading.mnydpv', '/expertises/agilite-coaching', 'heading', 'Ce que The Porters prend en charge'),
  ('pages.expertises.agilite-coaching.auto.heading.zze2uw', '/expertises/agilite-coaching', 'heading', 'Boucles de retour courtes'),
  ('pages.expertises.agilite-coaching.auto.list_item.15i5z1e', '/expertises/agilite-coaching', 'list_item', '<span class="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Design Thinking'),
  ('pages.expertises.agilite-coaching.auto.list_item.19lt70h', '/expertises/agilite-coaching', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Conception centrée utilisateur et tests continus'),
  ('pages.expertises.agilite-coaching.auto.list_item.1aqzvcy', '/expertises/agilite-coaching', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Vision produit, roadmap et priorisation du backlog'),
  ('pages.expertises.agilite-coaching.auto.list_item.1omw58p', '/expertises/agilite-coaching', 'list_item', '<span class="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>SAFe'),
  ('pages.expertises.agilite-coaching.auto.list_item.1tzoiuk', '/expertises/agilite-coaching', 'list_item', '<span class="mt-2 h-2 w-2 shrink-0 rounded-full bg-porters-gold"></span>Coordination multi-équipes et Agile Release Train'),
  ('pages.expertises.agilite-coaching.auto.list_item.4fozgw', '/expertises/agilite-coaching', 'list_item', '<span class="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-porters-gold"></span>Lean'),
