  ('pages.qui-sommes-nous.auto.paragraph.ihwokj', '/qui-sommes-nous', 'paragraph', 'Accompagnement des équipes techniques et métiers'),
  ('pages.qui-sommes-nous.auto.paragraph.ik7xy3', '/qui-sommes-nous', 'paragraph', 'Les profils Cloud et DevOps sont régulièrement sollicités pour des transformations techniques complexes, des migrations ou des phases d’industrialisation. Le portage salarial leur permet d’intervenir avec autonomie tout en déléguant la gestion administrative de leur activité.'),
  ('pages.qui-sommes-nous.auto.paragraph.illyuu', '/qui-sommes-nous', 'paragraph', 'Soutien dans les échanges avec le client'),
  ('pages.qui-sommes-nous.auto.paragraph.im7l07', '/qui-sommes-nous', 'paragraph', 'Un consultant ou une entreprise doit savoir qui contacter et obtenir une réponse liée à sa situation.'),
  ('pages.qui-sommes-nous.auto.paragraph.inpckd', '/qui-sommes-nous', 'paragraph', 'DevOps Engineer'),
  ('pages.qui-sommes-nous.auto.paragraph.iruxc2', '/qui-sommes-nous', 'paragraph', 'Sensibilisation'),
