  ('pages.qui-sommes-nous.auto.paragraph.p2zatl', '/qui-sommes-nous', 'paragraph', 'Nous partons du métier, du niveau de responsabilité et de la réalité de la mission pour proposer un cadre pertinent.'),
  ('pages.qui-sommes-nous.auto.paragraph.p3hou5', '/qui-sommes-nous', 'paragraph', 'Ces experts assurent la coordination entre les directions, les utilisateurs, les équipes techniques et les partenaires. Ils structurent les priorités, définissent les objectifs, sécurisent les délais et veillent à la qualité de l’exécution.'),
  ('pages.qui-sommes-nous.auto.paragraph.p4g2yj', '/qui-sommes-nous', 'paragraph', 'Stratégie et pilotage produit'),
  ('pages.qui-sommes-nous.auto.paragraph.p8iaf5', '/qui-sommes-nous', 'paragraph', 'FinOps'),
  ('pages.qui-sommes-nous.auto.paragraph.pjzjs9', '/qui-sommes-nous', 'paragraph', 'Cadrer les besoins, aligner les équipes et piloter la réalisation de produits et de projets numériques à forte valeur métier.'),
