  ('pages.qui-sommes-nous.auto.paragraph.q425xy', '/qui-sommes-nous', 'paragraph', 'The Porters porte les professionnels capables de transformer une ambition stratégique ou un besoin métier en produit, en service ou en projet concret.'),
  ('pages.qui-sommes-nous.auto.paragraph.q4c9sr', '/qui-sommes-nous', 'paragraph', 'Domaine sélectionné'),
