  ('pages.tarifs.auto.paragraph.10n12s0', '/tarifs', 'paragraph', 'Frais de gestion'),
  ('pages.tarifs.auto.paragraph.12lfp1m', '/tarifs', 'paragraph', 'Ils vous sont remboursés, ils ne sont pas financés par les frais de gestion. Seules les dépenses réelles, justifiées et liées à votre activité sont retenues. Le simulateur retient une hypothèse de 500 € par mois ; votre situation peut être très différente.'),
  ('pages.tarifs.auto.paragraph.13esgxj', '/tarifs', 'paragraph', 'Vous êtes couvert en cas de dommage causé chez un client.'),
